<?php

declare(strict_types=1);

namespace App\Api\Records;

use App\Api\Contracts\Domains\ApiSender;
use App\Support\CallKey;

/**
 * The API of Records, generated by php artisan journal:api; run it again instead of editing.
 */
final readonly class RecordApi
{
    public function __construct(private ApiSender $sender) {}

    public function addLink(
        string $source,
        string $target,
        CallKey $requestKey = new CallKey(),
    ): LinkChanged {
        return $this->sender->send(AddLinkPayload::from([
            'source' => $source,
            'target' => $target,
            'requestKey' => $requestKey,
        ]));
    }

    public function removeLink(
        string $source,
        string $target,
        CallKey $requestKey = new CallKey(),
    ): LinkChanged {
        return $this->sender->send(RemoveLinkPayload::from([
            'source' => $source,
            'target' => $target,
            'requestKey' => $requestKey,
        ]));
    }
}
